#!/usr/bin/env python3
# AI: below section was generated by an AI
"""
Save current WLED state as a preset for persistent storage.
WLED 0.11+ stores presets in /presets.json on device filesystem.
Presets survive reboot and can be recalled by ID (1-250).

Usage:
    python3 save_preset.py <preset_id> "<name>"
    python3 save_preset.py 100 "Jasmine Blooms"
    python3 save_preset.py --auto "Jasmine Blooms"    # auto-find free ID
    python3 save_preset.py --list                       # list existing presets
    python3 save_preset.py --help                       # show help

Output: JSON with {success, preset_id, name, message}
"""
import json
import os
import sys
import time
import urllib.request
import urllib.error

SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
CONFIG_PATH = os.path.join(os.path.dirname(SCRIPT_DIR), "config.json")


def load_config():
    with open(CONFIG_PATH, "r", encoding="utf-8") as f:
        return json.load(f)


def get_wled_ip():
    """Health-checked WLED IP via discover_wled.resolve_ip().

    The raw .wled_cache.json is deliberately NOT read here: a stale cache used
    to be returned unverified, which sent writes to an offline device.
    """
    try:
        if SCRIPT_DIR not in sys.path:
            sys.path.insert(0, SCRIPT_DIR)
        import discover_wled
        return discover_wled.resolve_ip()
    except Exception:
        return load_config().get("wled", {}).get("ip", "")


def wled_request(ip, path, method="GET", data=None, timeout=5):
    if not ip:
        return {"error": "WLED IP not configured. Run discover_wled.py first or set ip in config.json"}
    url = f"http://{ip}{path}"
    req = urllib.request.Request(url, headers={"User-Agent": "DoubaoWledSkill/1.0"})
    if method == "POST" and data is not None:
        req.data = json.dumps(data, ensure_ascii=False).encode("utf-8")
        req.add_header("Content-Type", "application/json")
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            body = resp.read().decode("utf-8")
            try:
                return json.loads(body) if body else {}
            except json.JSONDecodeError:
                return {"raw": body}
    except Exception as e:
        return {"error": str(e)}


def list_presets(ip):
    """Fetch existing presets from WLED.
    Returns dict like {"0": {...}, "1": {...}} or empty dict on failure.
    """
    result = wled_request(ip, "/presets.json", method="GET")
    if isinstance(result, dict) and "error" not in result:
        return result
    # Fallback: try /edit?list=/ to list files (returns HTML, hard to parse)
    # If both fail, return empty dict so find_free_preset_id can still work
    return {}


def find_free_preset_id(ip, id_start=100, id_end=250):
    """Find a free preset ID in the configured range."""
    presets = list_presets(ip)
    used_ids = set()
    if isinstance(presets, dict):
        for k in presets.keys():
            try:
                used_ids.add(int(k))
            except (ValueError, TypeError):
                continue
    for pid in range(id_start, id_end + 1):
        if pid not in used_ids:
            return pid
    return None


def save_preset(preset_id, name):
    """Save current WLED state as a preset.

    Two traps this function exists to survive, both measured on WLED 16.0.1:

    1. POST {"psave": N} is answered with {"success": true} even when nothing is
       written. It only queues `presetToSave`; the actual file write happens in
       handlePresets() -> doSaveState() on a later main-loop pass.
    2. That main-loop block is skipped entirely while realtimeMode is set
       (wled.cpp:131), so with a screen-sync stream running the preset is
       silently thrown away - possibly minutes later, when the queue finally
       flushes and writes whatever state exists *then*.

    So: take control of the strip first (exit realtime, and seize the realtime
    override when a stream insists on staying), then poll /presets.json until
    the entry really exists, and report success only if it does.
    """
    ip = get_wled_ip()
    if not ip:
        return {"success": False, "message": "WLED IP not configured. Run discover_wled.py first or set ip in config.json"}

    # Write guard: presets are device writes.
    try:
        from guard import require_write
    except ImportError:
        return {"success": False, "blocked": True, "reason": "guard_missing",
                "message": "写入守卫 scripts/guard.py 缺失，已拒绝写入。"}
    blocked = require_write(action="save_preset")
    if blocked:
        return blocked

    # Realtime must be cleared or the save is queued and never flushed.
    realtime = None
    try:
        sys.path.insert(0, SCRIPT_DIR)
        from apply_recipe import stop_udp_realtime
        realtime = stop_udp_realtime(ip)
    except Exception as exc:
        realtime = {"success": False, "message": "realtime takeover skipped: %s" % exc}

    # WLED API: POST /json/state {"psave": <id>, "n": "<name>"}
    state = {"psave": preset_id}
    if name:
        state["n"] = name

    result = wled_request(ip, "/json/state", method="POST", data=state)

    # The response is not trustworthy (see docstring) - poll the file instead.
    saved_ok = False
    for _ in range(10):
        time.sleep(0.3)
        verify = list_presets(ip)
        if isinstance(verify, dict) and str(preset_id) in verify:
            saved_ok = True
            break

    out = {
        "success": ("error" not in result) and saved_ok,
        "preset_id": preset_id,
        "name": name,
        "wled_response": result,
        "verified": saved_ok,
        "realtime": realtime,
        "message": (f"Preset saved as ID {preset_id} '{name}'" if saved_ok
                    else f"Preset {preset_id} was NOT persisted to /presets.json "
                         f"(device answered {'error' if 'error' in result else 'success'} but the file has no such entry)")
    }
    if not saved_ok:
        out["success"] = False
        if isinstance(realtime, dict) and realtime.get("contested"):
            out["reason"] = "realtime_contested"
            out["message"] += " — 设备正被外部实时流占用且未接管优先级，预设保存会被丢弃。"
    return out


def main():
    if "--help" in sys.argv or "-h" in sys.argv:
        print(__doc__)
        sys.exit(0)

    config = load_config()
    storage_cfg = config.get("recipe_storage", {})
    id_start = storage_cfg.get("preset_id_start", 100)
    id_end = storage_cfg.get("preset_id_end", 250)

    if "--list" in sys.argv:
        ip = get_wled_ip()
        if not ip:
            print(json.dumps({"success": False, "message": "WLED IP not configured"}, ensure_ascii=False))
            sys.exit(1)
        presets = list_presets(ip)
        print(json.dumps({"success": True, "presets": presets, "ip": ip}, indent=2, ensure_ascii=False))
        return

    if "--auto" in sys.argv:
        name_idx = sys.argv.index("--auto") + 1
        name = sys.argv[name_idx] if name_idx < len(sys.argv) else "Unnamed Recipe"
        ip = get_wled_ip()
        if not ip:
            print(json.dumps({"success": False, "message": "WLED IP not configured. Run discover_wled.py first"}, ensure_ascii=False))
            sys.exit(1)
        pid = find_free_preset_id(ip, id_start, id_end)
        if pid is None:
            print(json.dumps({"success": False, "message": f"No free preset ID in range {id_start}-{id_end}"}, ensure_ascii=False))
            sys.exit(1)
    else:
        if len(sys.argv) < 3:
            print(json.dumps({"success": False, "message": "Usage: save_preset.py <preset_id> <name>  OR  save_preset.py --auto <name>  OR  save_preset.py --list"}, ensure_ascii=False))
            sys.exit(1)
        pid = int(sys.argv[1])
        name = sys.argv[2]
        if pid < id_start or pid > id_end:
            print(json.dumps({"success": False, "message": f"Preset ID must be in range {id_start}-{id_end}"}, ensure_ascii=False))
            sys.exit(1)

    result = save_preset(pid, name)
    print(json.dumps(result, indent=2, ensure_ascii=False))
    sys.exit(0 if result.get("success") else 1)


if __name__ == "__main__":
    main()
# AI: end
